INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bb5f7ef6-03cd-5d08-9e86-38e4b8be4405', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', $$A Layer 3 VPN site advertises a route with route target 65000:100. The receiving PE has a VRF importing 65000:100. What is the expected result?$$::text, $$[{"id": "A", "text": "The next-hop remains unchanged unless 'neighbor next-hop-self' is configured.", "is_correct": false}, {"id": "B", "text": "The route is installed into the matching VRF routing table.", "is_correct": true}, {"id": "C", "text": "The local PE installs the MAC in its bridge domain forwarding table.", "is_correct": false}, {"id": "D", "text": "The pseudowire remains down until LDP session to the remote PE is established.", "is_correct": false}]$$::jsonb, $$Given A Layer 3 VPN site advertises a route with route target 65000:100. and The receiving PE has a VRF importing 65000:100., the result is: The route is installed into the matching VRF routing table.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$7.0 Layer 3 VPN$$::text, 10.0, '0162286b58535526', true) ON CONFLICT (id) DO NOTHING;
